use std::collections::HashMap;

use crate::solver::SolverProblem;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Task {
    pub template: usize,
    pub group: usize,
    pub weight: u64,
    pub class: u64,
    pub pinned: bool,
}

#[derive(Clone, Debug)]
pub enum Edit {
    Move(usize, usize), Weight(usize, u64), Class(usize, u64), Bind(usize, usize),
    Pin(usize, bool), Quota(usize, u64), Budget(usize, u64), Cap(usize, u64),
}

#[derive(Clone, Default)]
pub struct Query { pub groups: Vec<usize>, pub nodes: Vec<usize>, pub tasks: Vec<usize> }

pub struct Certificate {
    pub totals: [u64; 4],
    pub groups: Vec<[i64; 8]>,
    pub nodes: Vec<[u64; 3]>,
    pub tasks: Vec<[u64; 6]>,
}

pub struct Outcome {
    pub accepted: bool,
    pub revision: u64,
    pub violations: Option<[u64; 4]>,
    pub certificate: Certificate,
}

/// Snapshot of one task as it was in the committed state.
#[derive(Clone, Copy)]
struct TaskSnap {
    template: usize,
    group: usize,
    weight: u64,
    class: u64,
    pinned: bool,
}

/// Inverse operation used to roll a rejected proposal back.
enum Undo {
    Move(usize, usize),
    Weight(usize, u64),
    Class(usize, u64),
    Bind(usize, usize),
    Pin(usize, bool),
    Quota(usize, u64),
    Budget(usize, u64),
    Cap(usize, u64),
}

/// Transactional cache-group ledger.
///
/// The ledger owns the committed configuration of one session: per group
/// quota/budget, per task template/group/weight/class/pin and per node
/// capacity.  Derived aggregates (group footprints, node reservations,
/// group loads, class sets) are maintained incrementally so that a
/// transaction costs time proportional to the edits it carries.
pub struct Ledger {
    num_nodes: usize,
    num_groups: usize,
    num_tasks: usize,
    fp_words: usize,
    caps: Vec<u64>,
    group_quota: Vec<u64>,
    group_budget: Vec<u64>,
    task_template: Vec<usize>,
    task_group: Vec<usize>,
    task_weight: Vec<u64>,
    task_class: Vec<u64>,
    task_pinned: Vec<bool>,
    tmpl_domain: Vec<i64>,
    tmpl_fp: Vec<u64>,
    group_members: Vec<u32>,
    group_load: Vec<u64>,
    group_pins: Vec<u32>,
    group_fp_size: Vec<u32>,
    group_counts: Vec<u32>,
    group_keys: Vec<HashMap<(i64, i64), u32>>,
    group_domain: Vec<i64>,
    group_class: Vec<i64>,
    usage: Vec<i64>,
    slots: i64,
    total_weight: i64,
    total_pins: i64,
    active_groups: i64,
    revision: u64,
    tx_counter: u64,
    task_mark: Vec<u64>,
    group_mark: Vec<u64>,
}

impl Ledger {
    pub fn new(
        problem: &SolverProblem,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
        let num_nodes = problem.num_nodes;
        if capacities.len() != num_nodes {
            return Err("capacity count mismatch".into());
        }
        let num_groups = quotas.len();
        if budgets.len() != num_groups {
            return Err("group count mismatch".into());
        }
        let num_tasks = tasks.len();
        let num_templates = problem.demands.len();
        let fp_words = (num_nodes + 63) / 64;

        let mut node_domain = vec![-1i64; num_nodes];
        for (index, members) in problem.source_merge_groups.iter().enumerate() {
            for &node in members {
                if node < num_nodes {
                    node_domain[node] = index as i64;
                }
            }
        }
        let mut tmpl_domain = Vec::with_capacity(num_templates);
        let mut tmpl_fp = vec![0u64; num_templates * fp_words];
        for (index, demand) in problem.demands.iter().enumerate() {
            let domain = match problem.demand_merge_classes.as_ref() {
                Some(classes) => match classes.get(index) {
                    Some(&value) => value as i64,
                    None => return Err("class table mismatch".into()),
                },
                None => {
                    if demand.src >= num_nodes {
                        return Err("demand source out of range".into());
                    }
                    node_domain[demand.src]
                }
            };
            tmpl_domain.push(domain);
            let base = index * fp_words;
            for &node in &demand.footprint {
                if node < num_nodes {
                    tmpl_fp[base + node / 64] |= 1u64 << (node % 64);
                }
            }
        }

        let mut ledger = Ledger {
            num_nodes,
            num_groups,
            num_tasks,
            fp_words,
            caps: capacities,
            group_quota: quotas,
            group_budget: budgets,
            task_template: Vec::with_capacity(num_tasks),
            task_group: Vec::with_capacity(num_tasks),
            task_weight: Vec::with_capacity(num_tasks),
            task_class: Vec::with_capacity(num_tasks),
            task_pinned: Vec::with_capacity(num_tasks),
            tmpl_domain,
            tmpl_fp,
            group_members: vec![0; num_groups],
            group_load: vec![0; num_groups],
            group_pins: vec![0; num_groups],
            group_fp_size: vec![0; num_groups],
            group_counts: vec![0; num_groups * num_nodes],
            group_keys: (0..num_groups).map(|_| HashMap::new()).collect(),
            group_domain: vec![-1; num_groups],
            group_class: vec![-1; num_groups],
            usage: vec![0; num_nodes],
            slots: 0,
            total_weight: 0,
            total_pins: 0,
            active_groups: 0,
            revision: 0,
            tx_counter: 0,
            task_mark: vec![0; num_tasks],
            group_mark: vec![0; num_groups],
        };

        for task in &tasks {
            if task.template >= num_templates || task.group >= num_groups {
                return Err("task out of range".into());
            }
            ledger.task_template.push(task.template);
            ledger.task_group.push(task.group);
            ledger.task_weight.push(task.weight);
            ledger.task_class.push(task.class);
            ledger.task_pinned.push(task.pinned);
            ledger.insert_task(task.group, task.template, task.weight, task.class, task.pinned);
        }
        ledger.refresh_group_labels();

        ledger.check_legal()?;
        Ok(ledger)
    }

    fn template_nodes(&self, template: usize) -> Vec<u32> {
        let mut nodes = Vec::new();
        let base = template * self.fp_words;
        for word_index in 0..self.fp_words {
            let mut bits = self.tmpl_fp[base + word_index];
            while bits != 0 {
                let bit = bits.trailing_zeros() as usize;
                bits &= bits - 1;
                let node = word_index * 64 + bit;
                if node < self.num_nodes {
                    nodes.push(node as u32);
                }
            }
        }
        nodes
    }

    fn add_usage(&mut self, node: usize, delta: i64) {
        self.usage[node] += delta;
        self.slots += delta;
    }

    fn inc_key(&mut self, group: usize, key: (i64, i64)) {
        let entry = self.group_keys[group].entry(key).or_insert(0);
        *entry += 1;
    }

    fn dec_key(&mut self, group: usize, key: (i64, i64)) {
        if let Some(count) = self.group_keys[group].get_mut(&key) {
            if *count > 0 {
                *count -= 1;
                if *count == 0 {
                    self.group_keys[group].remove(&key);
                }
            }
        }
    }

    /// Adds one task to a group footprint/aggregate set.
    fn insert_task(&mut self, group: usize, template: usize, weight: u64, class: u64, pinned: bool) {
        self.group_members[group] += 1;
        self.group_load[group] += weight;
        if pinned {
            self.group_pins[group] += 1;
            self.total_pins += 1;
        }
        self.total_weight += weight as i64;
        let domain = self.tmpl_domain[template];
        self.inc_key(group, (domain, class as i64));
        let quota = self.group_quota[group] as i64;
        let offset = group * self.num_nodes;
        for node in self.template_nodes(template) {
            let node = node as usize;
            let index = offset + node;
            self.group_counts[index] += 1;
            if self.group_counts[index] == 1 {
                self.group_fp_size[group] += 1;
                self.add_usage(node, quota);
            }
        }
    }

    /// Removes one task from a group footprint/aggregate set.
    fn erase_task(&mut self, group: usize, template: usize, weight: u64, class: u64, pinned: bool) {
        self.group_members[group] -= 1;
        self.group_load[group] -= weight;
        if pinned {
            self.group_pins[group] -= 1;
            self.total_pins -= 1;
        }
        self.total_weight -= weight as i64;
        let domain = self.tmpl_domain[template];
        self.dec_key(group, (domain, class as i64));
        let quota = self.group_quota[group] as i64;
        let offset = group * self.num_nodes;
        for node in self.template_nodes(template) {
            let node = node as usize;
            let index = offset + node;
            if self.group_counts[index] > 0 {
                self.group_counts[index] -= 1;
                if self.group_counts[index] == 0 {
                    self.group_fp_size[group] -= 1;
                    self.add_usage(node, -quota);
                }
            }
        }
    }

    fn apply_move(&mut self, task: usize, new_group: usize) {
        let old_group = self.task_group[task];
        if old_group == new_group {
            return;
        }
        let template = self.task_template[task];
        let weight = self.task_weight[task];
        let class = self.task_class[task];
        let pinned = self.task_pinned[task];
        self.erase_task(old_group, template, weight, class, pinned);
        self.insert_task(new_group, template, weight, class, pinned);
        self.task_group[task] = new_group;
    }

    fn apply_bind(&mut self, task: usize, new_template: usize) {
        let old_template = self.task_template[task];
        if old_template == new_template {
            return;
        }
        let group = self.task_group[task];
        let class = self.task_class[task];
        let quota = self.group_quota[group] as i64;
        let offset = group * self.num_nodes;
        for node in self.template_nodes(old_template) {
            let node = node as usize;
            let index = offset + node;
            if self.group_counts[index] > 0 {
                self.group_counts[index] -= 1;
                if self.group_counts[index] == 0 {
                    self.group_fp_size[group] -= 1;
                    self.add_usage(node, -quota);
                }
            }
        }
        for node in self.template_nodes(new_template) {
            let node = node as usize;
            let index = offset + node;
            self.group_counts[index] += 1;
            if self.group_counts[index] == 1 {
                self.group_fp_size[group] += 1;
                self.add_usage(node, quota);
            }
        }
        self.dec_key(group, (self.tmpl_domain[old_template], class as i64));
        self.inc_key(group, (self.tmpl_domain[new_template], class as i64));
        self.task_template[task] = new_template;
    }

    fn apply_weight(&mut self, task: usize, weight: u64) {
        let old = self.task_weight[task];
        if old == weight {
            return;
        }
        let group = self.task_group[task];
        self.group_load[group] = self.group_load[group] - old + weight;
        self.total_weight += weight as i64 - old as i64;
        self.task_weight[task] = weight;
    }

    fn apply_class(&mut self, task: usize, class: u64) {
        let old = self.task_class[task];
        if old == class {
            return;
        }
        let group = self.task_group[task];
        let template = self.task_template[task];
        let domain = self.tmpl_domain[template];
        self.dec_key(group, (domain, old as i64));
        self.inc_key(group, (domain, class as i64));
        self.task_class[task] = class;
    }

    fn apply_pin(&mut self, task: usize, pinned: bool) {
        let old = self.task_pinned[task];
        if old == pinned {
            return;
        }
        let group = self.task_group[task];
        if pinned {
            self.group_pins[group] += 1;
            self.total_pins += 1;
        } else {
            self.group_pins[group] -= 1;
            self.total_pins -= 1;
        }
        self.task_pinned[task] = pinned;
    }

    fn apply_quota(&mut self, group: usize, quota: u64) {
        let old = self.group_quota[group];
        if old == quota {
            return;
        }
        let delta = quota as i64 - old as i64;
        let offset = group * self.num_nodes;
        for node in 0..self.num_nodes {
            if self.group_counts[offset + node] > 0 {
                self.add_usage(node, delta);
            }
        }
        self.group_quota[group] = quota;
    }

    fn apply_budget(&mut self, group: usize, budget: u64) {
        self.group_budget[group] = budget;
    }

    fn apply_cap(&mut self, node: usize, capacity: u64) {
        self.caps[node] = capacity;
    }

    fn undo(&mut self, undo: &Undo) {
        match undo {
            Undo::Move(task, group) => self.apply_move(*task, *group),
            Undo::Weight(task, weight) => self.apply_weight(*task, *weight),
            Undo::Class(task, class) => self.apply_class(*task, *class),
            Undo::Bind(task, template) => self.apply_bind(*task, *template),
            Undo::Pin(task, pinned) => self.apply_pin(*task, *pinned),
            Undo::Quota(group, quota) => self.apply_quota(*group, *quota),
            Undo::Budget(group, budget) => self.apply_budget(*group, *budget),
            Undo::Cap(node, capacity) => self.apply_cap(*node, *capacity),
        }
    }

    /// Recomputes the committed (domain, class) label of every group.
    fn refresh_group_labels(&mut self) {
        for group in 0..self.num_groups {
            if self.group_members[group] == 0 {
                self.group_domain[group] = -1;
                self.group_class[group] = -1;
                continue;
            }
            let mut label: Option<(i64, i64)> = None;
            for &key in self.group_keys[group].keys() {
                label = Some(key);
                break;
            }
            match label {
                Some((domain, class)) => {
                    self.group_domain[group] = domain;
                    self.group_class[group] = class;
                }
                None => {
                    self.group_domain[group] = -1;
                    self.group_class[group] = -1;
                }
            }
        }
    }

    /// True when the current configuration satisfies every legality rule.
    fn check_legal(&self) -> Result<(), String> {
        for group in 0..self.num_groups {
            if self.group_members[group] == 0 {
                continue;
            }
            if self.group_keys[group].len() > 1 {
                return Err("mixed group".into());
            }
            if self.group_quota[group] == 0 {
                return Err("empty quota".into());
            }
            if self.group_load[group] > self.group_quota[group].saturating_mul(self.group_budget[group]) {
                return Err("work budget".into());
            }
        }
        for node in 0..self.num_nodes {
            if self.usage[node] > self.caps[node] as i64 {
                return Err("node capacity".into());
            }
        }
        Ok(())
    }

    pub fn certificate(&self, query: &Query) -> Certificate {
        let mut groups = Vec::with_capacity(query.groups.len());
        for &group in &query.groups {
            groups.push([
                group as i64,
                self.group_members[group] as i64,
                self.group_load[group] as i64,
                self.group_quota[group] as i64,
                self.group_budget[group] as i64,
                self.group_fp_size[group] as i64,
                self.group_domain[group],
                self.group_class[group],
            ]);
        }
        let mut nodes = Vec::with_capacity(query.nodes.len());
        for &node in &query.nodes {
            nodes.push([node as u64, self.usage[node] as u64, self.caps[node]]);
        }
        let mut tasks = Vec::with_capacity(query.tasks.len());
        for &task in &query.tasks {
            tasks.push([
                task as u64,
                self.task_group[task] as u64,
                self.task_template[task] as u64,
                self.task_weight[task],
                self.task_class[task],
                self.task_pinned[task] as u64,
            ]);
        }
        Certificate {
            totals: [
                self.active_groups as u64,
                self.slots as u64,
                self.total_weight as u64,
                self.total_pins as u64,
            ],
            groups,
            nodes,
            tasks,
        }
    }

    pub fn transact(&mut self, expected: u64, edits: &[Edit], query: &Query) -> Outcome {
        if expected != self.revision {
            return Outcome {
                accepted: false,
                revision: self.revision,
                violations: None,
                certificate: self.certificate(query),
            };
        }

        self.tx_counter += 1;
        let stamp = self.tx_counter;

        // Snapshot the committed values of every task and group touched by
        // this proposal: pin protection is judged against the state at the
        // beginning of the transaction.
        let mut edited_tasks: Vec<usize> = Vec::new();
        let mut quota_groups: Vec<usize> = Vec::new();
        for edit in edits {
            match edit {
                Edit::Move(task, _) | Edit::Weight(task, _) | Edit::Class(task, _)
                | Edit::Bind(task, _) | Edit::Pin(task, _) => {
                    if self.task_mark[*task] != stamp {
                        self.task_mark[*task] = stamp;
                        edited_tasks.push(*task);
                    }
                }
                Edit::Quota(group, _) => {
                    if self.group_mark[*group] != stamp {
                        self.group_mark[*group] = stamp;
                        quota_groups.push(*group);
                    }
                }
                Edit::Budget(_, _) | Edit::Cap(_, _) => {}
            }
        }
        let mut task_snaps: Vec<(usize, TaskSnap)> = Vec::with_capacity(edited_tasks.len());
        for &task in &edited_tasks {
            task_snaps.push((
                task,
                TaskSnap {
                    template: self.task_template[task],
                    group: self.task_group[task],
                    weight: self.task_weight[task],
                    class: self.task_class[task],
                    pinned: self.task_pinned[task],
                },
            ));
        }
        let mut quota_snaps: Vec<(usize, u64, u32)> = Vec::with_capacity(quota_groups.len());
        for &group in &quota_groups {
            quota_snaps.push((group, self.group_quota[group], self.group_pins[group]));
        }

        // Apply the proposal.
        let mut undo: Vec<Undo> = Vec::with_capacity(edits.len());
        let mut touched: Vec<usize> = Vec::new();
        for edit in edits {
            match edit {
                Edit::Move(task, group) => {
                    self.touch(self.task_group[*task], &mut touched);
                    self.touch(self.task_group[*task], &mut touched);
                    let old = self.task_group[*task];
                    self.apply_move(*task, *group);
                    self.touch(*group, &mut touched);
                    undo.push(Undo::Move(*task, old));
                }
                Edit::Weight(task, weight) => {
                    self.touch(self.task_group[*task], &mut touched);
                    let old = self.task_weight[*task];
                    self.apply_weight(*task, *weight);
                    undo.push(Undo::Weight(*task, old));
                }
                Edit::Class(task, class) => {
                    self.touch(self.task_group[*task], &mut touched);
                    let old = self.task_class[*task];
                    self.apply_class(*task, *class);
                    undo.push(Undo::Class(*task, old));
                }
                Edit::Bind(task, template) => {
                    self.touch(self.task_group[*task], &mut touched);
                    let old = self.task_template[*task];
                    self.apply_bind(*task, *template);
                    undo.push(Undo::Bind(*task, old));
                }
                Edit::Pin(task, pinned) => {
                    self.touch(self.task_group[*task], &mut touched);
                    let old = self.task_pinned[*task];
                    self.apply_pin(*task, *pinned);
                    undo.push(Undo::Pin(*task, old));
                }
                Edit::Quota(group, quota) => {
                    self.touch(*group, &mut touched);
                    let old = self.group_quota[*group];
                    self.apply_quota(*group, *quota);
                    undo.push(Undo::Quota(*group, old));
                }
                Edit::Budget(group, budget) => {
                    self.touch(*group, &mut touched);
                    let old = self.group_budget[*group];
                    self.apply_budget(*group, *budget);
                    undo.push(Undo::Budget(*group, old));
                }
                Edit::Cap(node, capacity) => {
                    let old = self.caps[*node];
                    self.apply_cap(*node, *capacity);
                    undo.push(Undo::Cap(*node, old));
                }
            }
        }

        // Violation counts of the proposed final state.
        let mut capacity_violations = 0u64;
        for node in 0..self.num_nodes {
            if self.usage[node] > self.caps[node] as i64 {
                capacity_violations += 1;
            }
        }
        let mut mixed_violations = 0u64;
        let mut work_violations = 0u64;
        for &group in &touched {
            if self.group_keys[group].len() > 1 {
                mixed_violations += 1;
            }
            if self.group_members[group] > 0 {
                let quota = self.group_quota[group];
                let budget = self.group_budget[group];
                if quota == 0 || self.group_load[group] > quota.saturating_mul(budget) {
                    work_violations += 1;
                }
            }
        }

        // Pin violations: a task pinned at the beginning of the transaction
        // keeps its group, template, weight, class and its old group's quota.
        let mut protected_changed = 0u64;
        let mut protected_changed_in_quota = 0u64;
        for (task, snap) in &task_snaps {
            if !snap.pinned {
                continue;
            }
            let fields_differ = self.task_template[*task] != snap.template
                || self.task_group[*task] != snap.group
                || self.task_weight[*task] != snap.weight
                || self.task_class[*task] != snap.class;
            if fields_differ {
                protected_changed += 1;
                for &(group, old_quota, _) in &quota_snaps {
                    if group == snap.group && self.group_quota[group] != old_quota {
                        protected_changed_in_quota += 1;
                        break;
                    }
                }
            }
        }
        let mut quota_protected = 0u64;
        for &(group, old_quota, old_pins) in &quota_snaps {
            if self.group_quota[group] != old_quota {
                quota_protected += old_pins as u64;
            }
        }
        let pin_violations = protected_changed + quota_protected - protected_changed_in_quota;

        let violations = [
            capacity_violations,
            mixed_violations,
            work_violations,
            pin_violations,
        ];
        let accepted = violations.iter().all(|&value| value == 0);
        if accepted {
            self.revision += 1;
            self.active_groups = 0;
            for group in 0..self.num_groups {
                if self.group_members[group] > 0 {
                    self.active_groups += 1;
                }
            }
            for &group in &touched {
                if self.group_members[group] == 0 {
                    self.group_domain[group] = -1;
                    self.group_class[group] = -1;
                } else {
                    let mut label: Option<(i64, i64)> = None;
                    for &key in self.group_keys[group].keys() {
                        label = Some(key);
                        break;
                    }
                    if let Some((domain, class)) = label {
                        self.group_domain[group] = domain;
                        self.group_class[group] = class;
                    }
                }
            }
        } else {
            for operation in undo.iter().rev() {
                self.undo(operation);
            }
        }

        Outcome {
            accepted,
            revision: self.revision,
            violations: Some(violations),
            certificate: self.certificate(query),
        }
    }

    fn touch(&mut self, group: usize, touched: &mut Vec<usize>) {
        if self.group_mark[group] != self.tx_counter {
            self.group_mark[group] = self.tx_counter;
            touched.push(group);
        }
    }
